import java.lang.management.ManagementFactory;
import java.util.*;
import shop.Order;
import shop.OrderIndex;

public class ZzEval {
    static final class Base {
        final Map<String, Order> m;
        Base(List<Order> os) { m = new HashMap<>(os.size()); for (Order o : os) m.put(o.tenant() + ":" + o.id(), o); }
        Order find(String t, int id) { return m.get(t + ":" + id); }
    }
    interface Finder { Order find(String t, int id); }
    static long sink;
    static long bytesPerFind(Finder f, String[] tenants) {
        var mx = (com.sun.management.ThreadMXBean) ManagementFactory.getThreadMXBean();
        for (int r = 0; r < 30; r++) for (int i = 0; i < 200_000; i++) { Order o = f.find(tenants[i % 500], i); if (o != null) sink += o.cents(); }
        long before = mx.getCurrentThreadAllocatedBytes();
        for (int r = 0; r < 10; r++) for (int i = 0; i < 200_000; i++) { Order o = f.find(tenants[i % 500], i); if (o != null) sink += o.cents(); }
        return (mx.getCurrentThreadAllocatedBytes() - before) / 2_000_000;
    }
    public static void main(String[] args) {
        if (args[0].equals("equiv")) {
            List<Order> os = new ArrayList<>(List.of(new Order("a:1", 2, 1), new Order("a", 12, 2), new Order("a", 1, 3),
                new Order("", 0, 4), new Order("żółw", -7, 5), new Order("t", Integer.MIN_VALUE, 6), new Order("t", Integer.MAX_VALUE, 7),
                new Order("dup", 9, 8), new Order("dup", 9, 9), new Order("A", 1, 10)));
            for (int i = 0; i < 1000; i++) os.add(new Order("tenant-" + (i % 37), i, i));
            OrderIndex cand = new OrderIndex(os); Base base = new Base(os);
            int bad = 0;
            if (cand.size() != base.m.size()) { System.out.println("MISMATCH size " + cand.size() + " vs " + base.m.size()); bad++; }
            String[] ts = {"a:1", "a", "", "żółw", "t", "dup", "A", "tenant-5", "tenant-50", "a:1:2", "zolw"};
            int[] ids = {2, 12, 1, 0, -7, Integer.MIN_VALUE, Integer.MAX_VALUE, 9, 5, 42, 3, -1};
            for (String t : ts) for (int id : ids) if (cand.find(t, id) != base.find(t, id)) { System.out.println("MISMATCH find(" + t + ", " + id + ")"); bad++; }
            for (Order o : os) if (cand.find(o.tenant(), o.id()) != base.find(o.tenant(), o.id())) { System.out.println("MISMATCH " + o); bad++; }
            System.out.println("equivalence mismatches=" + bad);
            System.exit(bad == 0 ? 0 : 1);
        }
        String[] tenants = new String[500];
        for (int t = 0; t < 500; t++) tenants[t] = "tenant-" + t;
        List<Order> os = new ArrayList<>();
        for (int i = 0; i < 200_000; i++) os.add(new Order(tenants[i % 500], i, i * 31L));
        Base base = new Base(os); OrderIndex cand = new OrderIndex(os);
        long b = bytesPerFind(base::find, tenants), c = bytesPerFind(cand::find, tenants);
        System.out.println("bytes per find: baseline " + b + ", candidate " + c);
        System.exit(c * 2 <= b ? 0 : 1);
    }
}
EOF
